#!/usr/bin/env python3
"""Creator OS — local-first content operations server. No third-party Python packages required. Optional Ollama integration."""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse
from urllib.request import Request, urlopen
import json, sqlite3, os, datetime

ROOT=os.path.dirname(os.path.abspath(__file__))
DB=os.path.join(ROOT,'creator_os.db')
PORT=int(os.getenv('PORT','8787'))
OLLAMA_URL=os.getenv('OLLAMA_BASE_URL','http://127.0.0.1:11434')
OLLAMA_MODEL=os.getenv('OLLAMA_MODEL','qwen2.5:7b')

HTML='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Creator OS</title><style>:root{--bg:#07090d;--p:#0d1118;--p2:#111722;--line:#1d2633;--text:#f5f7fb;--muted:#8d9aac;--a:#8b5cf6;--good:#34d399}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,sans-serif}.app{display:flex;min-height:100vh}.side{width:235px;background:#090c12;border-right:1px solid var(--line);padding:18px 14px;position:fixed;inset:0 auto 0 0}.brand{font-size:19px;font-weight:700;padding:12px}.brand b{color:#b99cff}.nav button{width:100%;background:none;border:0;color:#9aa6b8;text-align:left;padding:11px 12px;border-radius:10px;cursor:pointer}.nav button:hover,.nav button.active{background:#ffffff08;color:#fff}.bottom{position:absolute;bottom:18px;left:14px;right:14px}.main{margin-left:235px;flex:1;padding:30px;max-width:1500px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.eyebrow{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}h1{font-size:32px;margin:8px 0 5px}h2{font-size:18px;margin:0}.muted{color:var(--muted)}.grid{display:grid;gap:14px}.metrics{grid-template-columns:repeat(4,1fr);margin-top:26px}.cols{grid-template-columns:1.35fr .65fr;margin-top:14px}.panel{background:var(--p);border:1px solid var(--line);border-radius:17px;padding:18px}.metric{min-height:108px}.metric .v{font-size:28px;font-weight:700;margin-top:8px}.btn{border:1px solid var(--line);background:#111722;color:#fff;border-radius:10px;padding:9px 13px;cursor:pointer}.primary{background:var(--a);border-color:var(--a)}.row{display:flex;align-items:center;gap:12px}.between{justify-content:space-between}.job,.topic,.channel{background:var(--p2);border:1px solid var(--line);border-radius:13px;padding:13px}.list{display:grid;gap:8px;margin-top:14px}.badge{font-size:11px;border:1px solid var(--line);border-radius:999px;padding:4px 8px;color:#aab4c4}.bar{height:5px;background:#ffffff09;border-radius:20px;overflow:hidden}.bar i{display:block;height:100%;background:var(--a);border-radius:20px}.score{font-size:21px;color:#b99cff;font-weight:700}.topicgrid{grid-template-columns:repeat(2,1fr);margin-top:14px}.mini{font-size:11px;color:var(--muted)}input{width:100%;background:#080b10;color:#fff;border:1px solid var(--line);border-radius:10px;padding:11px;outline:none}.studio{margin-top:22px}.hidden{display:none}.result{white-space:pre-wrap;font:12px ui-monospace,monospace;color:#aeb8c7;background:#080b10;border:1px solid var(--line);padding:13px;border-radius:10px;max-height:420px;overflow:auto}@media(max-width:900px){.side{display:none}.main{margin-left:0;padding:18px}.metrics,.cols,.topicgrid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.metrics,.cols,.topicgrid{grid-template-columns:1fr}}</style></head><body><div class="app"><aside class="side"><div class="brand">Creator<b>OS</b><div class="mini" style="margin-top:4px">local content operating system</div></div><div class="nav"><button class="active" onclick="show('dashboard',this)">◈ Dashboard</button><button onclick="show('studio',this)">✦ Production Studio</button><button onclick="show('topics',this)">⌁ Topic Lab</button><button onclick="show('channels',this)">◉ Channels</button><button onclick="show('research',this)">▤ Research Vault</button><button onclick="show('analytics',this)">◫ Analytics</button><button onclick="show('blog',this)">✎ Blog</button></div><div class="bottom panel"><div class="mini">LOCAL ENGINE</div><div style="margin-top:8px"><span style="color:var(--good)">●</span> Ollama optional</div><div class="mini" style="margin-top:4px">No paid API required for the core app.</div></div></aside><main class="main"><section id="dashboard"><div class="top"><div><div class="eyebrow">Creator command center</div><h1>Build once. Publish everywhere.</h1><div class="muted">Demand-led research → original production → QA → human approval.</div></div><button class="btn primary" onclick="show('studio')">＋ New production</button></div><div class="grid metrics"><div class="panel metric"><div class="eyebrow">Active channels</div><div class="v">4</div><div class="mini">+ blog engine</div></div><div class="panel metric"><div class="eyebrow">In production</div><div class="v">3</div><div class="mini">1 needs review</div></div><div class="panel metric"><div class="eyebrow">Topic backlog</div><div class="v">24</div><div class="mini">6 high-confidence</div></div><div class="panel metric"><div class="eyebrow">System health</div><div class="v">98%</div><div class="mini">Local-first</div></div></div><div class="grid cols"><div class="panel"><div class="row between"><div><h2>Production queue</h2><div class="mini" style="margin-top:4px">No publishing happens behind your back.</div></div><span class="badge">human gate ON</span></div><div id="jobs" class="list"></div></div><div class="panel"><h2>Channel health</h2><div id="channels" class="list"></div></div></div><div class="panel" style="margin-top:14px"><div class="row"><div style="font-size:20px">⚠</div><div><b>Originality is a product feature.</b><div class="muted" style="margin-top:4px;line-height:1.6">The system can study what performs, but it does not copy another creator’s script, edit pattern, or assets. Every factual documentary gets a source-backed claim ledger.</div></div></div></div></section><section id="studio" class="hidden"><div class="eyebrow">Production studio</div><h1>Start a production</h1><div class="muted">The first gate creates a research contract. Generation comes after the evidence plan.</div><div class="panel studio"><label class="mini">TOPIC</label><div class="row" style="margin-top:8px"><input id="topicInput" value="Battle of Panipat"><button class="btn primary" onclick="plan()">Create plan</button></div><div id="planOut" style="margin-top:14px"></div></div></section><section id="topics" class="hidden"><div class="eyebrow">Topic lab</div><h1>Find the next video</h1><div class="muted">Score demand, originality, researchability and competition separately.</div><div id="topicList" class="grid topicgrid"></div></section><section id="channels" class="hidden"><div class="eyebrow">Channels</div><h1>Channel portfolio</h1><div id="channelList" class="list"></div></section><section id="research" class="hidden"><div class="eyebrow">Research vault</div><h1>Evidence before narration</h1><div class="panel studio"><p class="muted" style="line-height:1.7">Every documentary should eventually store: source URL, publisher, publication date, claim supported, confidence, conflicting evidence, usage rights, and the exact script sentence that uses it.</p><div class="result">Claim ledger example\n\nCLAIM: Every material historical statement needs a source record.\nSOURCE: primary/academic source\nCONFIDENCE: high\nSCRIPT USE: pending\nVISUAL PROVENANCE: pending\n\nThe production engine will reject factual claims without a source record.</div></div></section><section id="analytics" class="hidden"><div class="eyebrow">Analytics</div><h1>Learn what the audience rewards</h1><div class="panel studio"><p class="muted">The next connector will ingest YouTube Analytics and turn retention, CTR, returning viewers and traffic sources into production feedback—not vanity dashboards.</p><div class="grid metrics"><div class="panel metric"><div class="eyebrow">Retention</div><div class="v">—</div><div class="mini">Connect YouTube</div></div><div class="panel metric"><div class="eyebrow">CTR</div><div class="v">—</div><div class="mini">Connect YouTube</div></div><div class="panel metric"><div class="eyebrow">Returning</div><div class="v">—</div><div class="mini">Connect YouTube</div></div><div class="panel metric"><div class="eyebrow">Shorts → long</div><div class="v">—</div><div class="mini">Attribution later</div></div></div></div></section><section id="blog" class="hidden"><div class="eyebrow">Research Desk</div><h1>One research project, many outputs</h1><div class="panel studio"><div class="row between"><div><b>Master research package</b><div class="muted" style="margin-top:4px">Documentary + Shorts + article + social derivatives.</div></div><span class="badge">source-linked</span></div><div class="list"><div class="job">Article brief → 1,800–2,500 words</div><div class="job">FAQ + structured internal links</div><div class="job">5–8 Shorts candidates</div><div class="job">Thumbnail concepts</div></div></div></section></main></div><script>const ids=['dashboard','studio','topics','channels','research','analytics','blog'];function show(id,btn){ids.forEach(x=>document.getElementById(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');if(id==='topics')loadTopics();if(id==='channels')loadChannels()}async function j(u,o){let r=await fetch(u,o);return r.json()}async function loadJobs(){let d=await j('/api/jobs');document.getElementById('jobs').innerHTML=d.jobs.map(x=>`<div class="job"><div class="row between"><div><b>${x.title}</b><div class="mini" style="margin-top:4px">${x.kind} · ${x.stage} · ${x.updated_at}</div></div><span class="badge">${x.status}</span></div><div class="bar" style="margin-top:10px"><i style="width:${x.progress}%"></i></div></div>`).join('')}async function loadChannels(){let d=await j('/api/channels');document.getElementById('channelList').innerHTML=d.channels.map(x=>`<div class="channel row"><div style="font-size:22px">${x.kind==='gaming'?'🎮':x.kind==='kids'?'🧒':x.kind==='documentary'?'📚':x.kind==='tech'?'🤖':'✎'}</div><div style="flex:1"><b>${x.name}</b><div class="mini">${x.language} · ${x.cadence}</div></div><span class="badge">ready</span></div>`).join('');document.getElementById('channels').innerHTML=d.channels.slice(0,4).map(x=>`<div class="channel row"><div style="font-size:20px">${x.kind==='gaming'?'🎮':x.kind==='kids'?'🧒':x.kind==='documentary'?'📚':'🤖'}</div><div style="flex:1"><b>${x.name}</b><div class="mini">${x.cadence}</div></div><span style="color:var(--good);font-size:11px">healthy</span></div>`).join('')}async function loadTopics(){let d=await j('/api/topics');document.getElementById('topicList').innerHTML=d.topics.map(x=>`<div class="topic"><div class="row between"><div><b>${x.title}</b><div class="mini" style="margin-top:5px;line-height:1.5">${x.angle}</div></div><div class="score">${x.score}</div></div><div class="grid" style="grid-template-columns:repeat(4,1fr);gap:7px;margin-top:14px">${[['Demand',x.demand],['Originality',x.originality],['Research',x.researchability],['Competition',x.competition]].map(a=>`<div><div class="mini">${a[0]}</div><div class="bar" style="margin-top:5px"><i style="width:${a[1]}%"></i></div></div>`).join('')}</div><div class="row between" style="margin-top:13px"><span class="badge">${x.source_count} sources</span><span class="mini">${x.status}</span></div></div>`).join('')}async function plan(){let t=document.getElementById('topicInput').value.trim();if(!t)return;let out=document.getElementById('planOut');out.innerHTML='<div class="muted">Creating production contract…</div>';let d=await j('/api/plan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({topic:t})});out.innerHTML='<div class="result">'+JSON.stringify(d,null,2).replaceAll('<','&lt;')+'</div>'}loadJobs();loadChannels();</script></body></html>'''

def init():
    c=sqlite3.connect(DB)
    c.executescript('CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,name TEXT,kind TEXT,language TEXT,cadence TEXT,color TEXT); CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,angle TEXT,score INTEGER,demand INTEGER,competition INTEGER,originality INTEGER,researchability INTEGER,status TEXT,created_at TEXT); CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,channel_id TEXT,kind TEXT,status TEXT,stage TEXT,progress INTEGER,updated_at TEXT,error TEXT); CREATE TABLE IF NOT EXISTS sources(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER,url TEXT,title TEXT,source_type TEXT,trust INTEGER,notes TEXT);')
    if c.execute('SELECT COUNT(*) FROM channels').fetchone()[0]==0:c.executemany('INSERT INTO channels VALUES(?,?,?,?,?,?)',[('bgmi','BGMI Live','gaming','Hindi','3 lives / week','#f59e0b'),('kids','Hindi Kids Stories','kids','Hindi','5 videos / week','#22c55e'),('history','Itihas Uncovered','documentary','Hindi','2 documentaries / week','#a78bfa'),('tech','Tech Explained Hindi','tech','Hindi','2 videos / week','#38bdf8'),('blog','Research Desk','blog','Hindi + English','Daily','#fb7185')])
    if c.execute('SELECT COUNT(*) FROM topics').fetchone()[0]==0:c.executemany('INSERT INTO topics(title,angle,score,demand,competition,originality,researchability,status,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[('Battle of Panipat','The logistics, alliances and decisions that shaped the outcome before the main clash',92,91,76,94,97,'approved','2026-09-14'),('Nalanda: What Actually Happened?','Separate the popular destruction narrative from what primary and scholarly sources support',89,88,82,91,95,'candidate','2026-09-14'),('How UPI Became India’s Invisible Infrastructure','The technical and economic story behind India’s real-time payments scale',87,86,71,88,96,'candidate','2026-09-14'),('Subhas Chandra Bose: The Part of the Story We Skip','A source-led timeline of strategy, alliances and unresolved historical questions',85,87,81,90,93,'candidate','2026-09-14')])
    if c.execute('SELECT COUNT(*) FROM jobs').fetchone()[0]==0:c.executemany('INSERT INTO jobs(title,channel_id,kind,status,stage,progress,updated_at) VALUES(?,?,?,?,?,?,?)',[('Battle of Panipat — Unheard Real Story','history','documentary','running','research',64,'2 min ago'),('Chintu and the Lost Moon','kids','kids-story','review','qa',100,'18 min ago'),('Why Panipat Was Won Before the Battle','history','short','queued','ideation',0,'just now')])
    c.commit();c.close()

def ollama(prompt):
    try:
        payload=json.dumps({'model':OLLAMA_MODEL,'prompt':prompt,'stream':False}).encode();req=Request(OLLAMA_URL+'/api/generate',data=payload,headers={'Content-Type':'application/json'})
        with urlopen(req,timeout=90) as r:return json.loads(r.read()).get('response','')
    except Exception:return ''

def research_contract(topic):return {'topic':topic,'gates':['Demand signal collected','Primary/authoritative sources prioritized','Claim ledger created','Original angle separated from competitor narratives','Visual provenance recorded','Script QA completed','Human approval before publish'],'deliverables':['research brief','claim ledger','original outline','Hindi script','shot list','voice plan','thumbnail brief','blog article','shorts candidates']}

def jrows(c,q):return [dict(x) for x in c.execute(q).fetchall()]
class H(BaseHTTPRequestHandler):
    def js(self,o,s=200):
        b=json.dumps(o,ensure_ascii=False).encode();self.send_response(s);self.send_header('Content-Type','application/json; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
    def do_GET(self):
        p=urlparse(self.path).path;c=sqlite3.connect(DB);c.row_factory=sqlite3.Row
        if p=='/':
            b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b);return
        if p=='/api/channels':self.js({'channels':jrows(c,'SELECT * FROM channels ORDER BY rowid')});return
        if p=='/api/topics':self.js({'topics':jrows(c,'SELECT * FROM topics ORDER BY score DESC')});return
        if p=='/api/jobs':self.js({'jobs':jrows(c,'SELECT * FROM jobs ORDER BY id DESC')});return
        if p=='/api/health':self.js({'ok':True,'model':OLLAMA_MODEL});return
        self.js({'error':'not found'},404)
    def do_POST(self):
        p=urlparse(self.path).path;n=int(self.headers.get('Content-Length','0'));body=json.loads(self.rfile.read(n) or '{}')
        if p=='/api/plan':
            topic=str(body.get('topic','')).strip()
            if not topic:return self.js({'error':'topic required'},400)
            prompt=f'You are the research director for a Hindi documentary YouTube channel. Topic: {topic}. Give 5 original angles, likely viewer questions, authoritative source types, claims requiring verification, and visual opportunities. Do not imitate any existing creator.'
            ai=ollama(prompt);self.js({'ok':True,'topic':topic,'contract':research_contract(topic),'local_ai_plan':ai or 'Ollama unavailable — contract created; connect Ollama for the AI planning layer.'});return
        self.js({'error':'not found'},404)
if __name__=='__main__':init();print(f'Creator OS running at http://127.0.0.1:{PORT}');ThreadingHTTPServer(('0.0.0.0',PORT),H).serve_forever()
